// 一、工具函数
// 环境监测
function watch(obj, name, visited = new WeakSet()) {
    // 避免无限递归
    if (obj === null || typeof obj !== "object" || visited.has(obj)) {
        return obj;
    }

    visited.add(obj);

    // ---- BRAND CHECK 跳过表 ----
    const brandCheckedList = new WeakSet([
        window.crypto,
        window.crypto?.subtle,
        Crypto?.prototype,
        CryptoKey?.prototype,
        SubtleCrypto?.prototype,
    ]);

    // ---- 检测 brand-check 或已知不可代理对象 ----
    function isBrandChecked(o) {
        if (o === null || typeof o !== "object") return false;
        if (brandCheckedList.has(o)) return true;

        // 有些浏览器对象有 [[Brand]] 要求 this 必须是原生对象
        const safe = [
            "[object Crypto]",
            "[object SubtleCrypto]",
            "[object CryptoKey]",
            "[object Window]"
        ];

        try {
            const tag = Object.prototype.toString.call(o);
            if (safe.includes(tag)) {
                brandCheckedList.add(o);
                return true;
            }
        } catch (e) {
            return true;
        }

        return false;
    }

    // ---- 如果对象 brand-check，则不包装，直接返回原对象 ----
    if (isBrandChecked(obj)) {
        return obj;
    }

    return new Proxy(obj, {
        get(target, prop, receiver) {
            try {
                if (typeof prop === "symbol" || prop === "constructor" || prop === "__proto__")
                    return Reflect.get(target, prop, receiver);

                // 特殊处理 navigator.platform
                if (name === "navigator" && prop === "platform") {
                    console.log(`对象 => ${name} 特殊处理属性: ${String(prop)} 模拟值为: Win32`);
                    return "Win32";
                }

                const value = Reflect.get(target, prop, receiver);

                // ---- 子对象也进行 watch，但要避免 brand-check ----
                if (typeof value === "object" && value !== null) {
                    if (!isBrandChecked(value)) {
                        return watch(value, `${name}.${String(prop)}`, visited);
                    }
                }

                // 打印 undefined 访问
                if (value === undefined) {
                    console.log(`对象 => ${name}, 读取属性: ${String(prop)} 值为: undefined, 类型为: ${typeof value}`);
                }

                // 原型链检测
                if (!Object.prototype.hasOwnProperty.call(target, prop)) {
                    let current = target;
                    while (current) {
                        current = Object.getPrototypeOf(current);
                        if (current && Object.prototype.hasOwnProperty.call(current, prop)) {
                            console.log(`原型链检测:true (对象: ${name} 属性: ${prop})`);
                            break;
                        }
                    }
                }

                // 检测描述符
                const descriptor = Object.getOwnPropertyDescriptor(target, prop);
                if (descriptor) {
                    if (descriptor.get || descriptor.set) {
                        console.log(`特殊检测: 存在Getter/Setter (对象: ${name} 属性: ${String(prop)})`);
                    }
                    if (!descriptor.writable && !descriptor.get) {
                        console.log(`特殊检测: 只读属性 (对象: ${name} 属性: ${String(prop)})`);
                    }
                    if (!descriptor.configurable) {
                        console.log(`特殊检测: 不可配置属性 (对象: ${name} 属性: ${String(prop)})`);
                    }
                }

                return value;
            } catch (err) {
                // ✅ 关键：不再抛错，不会影响运行
                // console.warn(`get trap 捕获到安全错误 => ${name}.${String(prop)} (已自动跳过)`);
                return Reflect.get(target, prop);
            }
        },

        set(target, prop, val, receiver) {
            console.log(`对象 => ${name}, 设置属性: ${String(prop)} 值为: ${typeof val === 'function' ? 'function' : val}, 类型为: ${typeof val}`);
            return Reflect.set(target, prop, val, receiver);
        },

        has(target, prop) {
            console.log(`对象 => ${name} in 操作符检测属性: ${String(prop)}`);
            return Reflect.has(target, prop);
        },

        deleteProperty(target, prop) {
            console.log(`对象 => ${name} 删除属性: ${String(prop)}`);
            return Reflect.deleteProperty(target, prop);
        },

        ownKeys(target) {
            console.log(`对象 => ${name} 获取自身所有键`);
            return Reflect.ownKeys(target);
        },

        defineProperty(target, prop, descriptor) {
            console.log(`对象 => ${name} 定义属性: ${String(prop)}`);
            return Reflect.defineProperty(target, prop, descriptor);
        },

        setPrototypeOf(target, proto) {
            console.log(`特殊检测: setPrototypeOf 被调用 (对象: ${name})`);
            return Reflect.setPrototypeOf(target, proto);
        },

        getPrototypeOf(target) {
            console.log(`特殊检测: getPrototypeOf 被调用 (对象: ${name})`);
            return Reflect.getPrototypeOf(target);
        }
    });
}
//安全函数
const safeFunction = (function () {
    let initialized = false;
    let myFunction_toString_symbol;
    const set_native = function set_native(func, key, value) {
        Object.defineProperty(func, key, {
            value: value,
            writable: false,
            enumerable: false,
            configurable: false
        });
    };
    return function (func) {
        if (typeof func !== 'function') return;
        if (!initialized) {
            myFunction_toString_symbol = Symbol('functionToString');
            initialized = true;
        }
        const originalToString = func.toString;
        if (!func[myFunction_toString_symbol]) {
            set_native(func, myFunction_toString_symbol, originalToString);
            set_native(func, 'toString', function () {
                return originalToString.call(this);
            });
        }
    };
})();
//类构造函数
function createConstructor(constructorName, enableStrictMode, propertiesList, prototypeMethods, parentConstructorName) {
    const instancesData = {};
    const constructorFunction = function (element, propertySetter, validationToken) {
        if (enableStrictMode && !(validationToken && validationToken === "jxkj")) {
            throw new Error("Illegal constructor");
        }

        // 为实例添加Symbol.toStringTag
        Object.defineProperty(this, Symbol.toStringTag, {
            value: constructorName,
            writable: false,
            enumerable: false,
            configurable: false
        });

        // 为实例添加Symbol.toPrimitive
        Object.defineProperty(this, Symbol.toPrimitive, {
            value: function (hint) {
                switch (hint) {
                    case 'number':
                        return this._element ? instancesData[this._element].toString().length : 0;
                    case 'string':
                        return `[${constructorName} Instance]`;
                    default:
                        return `[object ${constructorName}]`;
                }
            },
            writable: false,
            enumerable: false,
            configurable: false
        });

        if (propertySetter && typeof propertySetter === "function") {
            propertySetter(this, instancesData[this._element]);
        }
        const instanceProperties = element && typeof element === "object" ? element : {};
        this._element = Symbol("_element");
        instancesData[this._element] = instanceProperties;
        if (element && typeof element === "object") {
            Object.keys(element).forEach(key => {
                if (!this[key]) {
                    this[key] = element[key];
                }
            });
        }
    };

    // 设置构造函数名称
    Object.defineProperty(constructorFunction, 'name', {value: constructorName});

    // 处理继承关系
    if (parentConstructorName && window[parentConstructorName]) {
        const ParentConstructor = window[parentConstructorName];
        constructorFunction.prototype = Object.create(ParentConstructor.prototype);
        Object.defineProperty(constructorFunction.prototype, 'constructor', {
            value: constructorFunction,
            writable: false,
            enumerable: false,
            configurable: false
        });
    }

    // 为构造函数本身添加Symbol.toStringTag
    Object.defineProperty(constructorFunction, Symbol.toStringTag, {
        value: constructorName,
        writable: false,
        enumerable: false,
        configurable: false
    });

    // 为构造函数本身添加Symbol.toPrimitive
    Object.defineProperty(constructorFunction, Symbol.toPrimitive, {
        value: function (hint) {
            switch (hint) {
                case 'number':
                    return constructorName.length;
                case 'string':
                    return `[Constructor ${constructorName}]`;
                default:
                    return constructorName;
            }
        },
        writable: false,
        enumerable: false,
        configurable: false
    });

    // 添加原型方法
    Object.keys(prototypeMethods).forEach(methodName => {
        constructorFunction.prototype[methodName] = prototypeMethods[methodName];
        if (typeof constructorFunction.prototype[methodName] === "function") {
            safeFunction(constructorFunction.prototype[methodName]);
        }
    });

    // 保护构造函数
    safeFunction(constructorFunction);

    // 挂载到全局
    window[constructorName] = constructorFunction;
    return constructorFunction;
};



